package com.gasczoology.invertebratelab.data

/** Draft five-mark questions for Unit VII chapters. DRAFT_UNVERIFIED; not part of the validated 86. */
object FurtherQuestions {
    private fun q(chapterId: String, n: Int, en: String, ta: String, vararg points: Pair<String, String>) = A5Question(
        id = "$chapterId-A5-$n",
        chapterId = chapterId,
        question = BilingualText(en, ta),
        answerPoints = points.map { BilingualText(it.first, it.second) },
    )

    val byChapter: Map<String, List<A5Question>> = listOf<A5Question>(
        q("u7-minor-annelids", 1, "Write notes on the Echiuroidea.", "எக்கியூராய்டியா பற்றிக் குறிப்பு எழுதுக.",
            "They are marine spoon worms with a sausage-shaped, unsegmented trunk." to "அவை தொத்திறைச்சி வடிவ, கண்டமற்ற உடற்பகுதியுள்ள கடல் கரண்டிப் புழுக்கள்.",
            "A flattened, non-retractile proboscis collects food particles from the mud." to "தட்டையான, உள்ளிழுக்க இயலாத துதிக்கை சேற்றிலிருந்து உணவுத் துகள்களைச் சேகரிக்கிறது.",
            "One pair of ventral chaetae lies behind the mouth, and the blood system is closed." to "வாய்க்குப் பின் ஒரு இணை வயிற்றுப்புற சீட்டாக்கள் உள்ளன; இரத்தத் தொகுதி மூடியது.",
            "Excretion is by nephridia and anal sacs, and the larva is a trochophore." to "கழிவு நீக்கம் நெஃப்ரிடியா, குத்துப் பைகளால்; புழு ட்ரோக்கோஃபோர்.",
            "Bonellia shows sexual dimorphism: a large female and a tiny parasitic male, with sex determined by the environment." to "பொனெல்லியா பால் இருவடிவம் காட்டுகிறது: பெரிய பெண், சிறிய ஒட்டுண்ணி ஆண்; பால் சூழலால் தீர்மானிக்கப்படுகிறது."),
        q("u7-minor-annelids", 2, "Compare the Sipunculoidea and the Priapulida.", "சிப்புங்குலாய்டியாவையும் பிரையாப்புலிடாவையும் ஒப்பிடுக.",
            "Both are unsegmented marine worms with a retractable introvert." to "இரண்டும் உள்ளிழுக்கும் இன்ட்ரோவெர்ட்டுள்ள கண்டமற்ற கடற்புழுக்கள்.",
            "Sipunculans have tentacles around the mouth, whereas priapulids have scalids and teeth." to "சிப்புங்குலன்களுக்கு வாயைச் சுற்றி உணர்நீட்சிகள்; பிரையாப்புலிட்களுக்கு ஸ்கேலிடுகளும் பற்களும்.",
            "Sipunculans have a U-shaped gut and haemerythrin; priapulids have a straight gut." to "சிப்புங்குலன்களுக்கு U வடிவ குடலும் ஹீமெரித்ரினும்; பிரையாப்புலிட்களுக்கு நேரான குடல்.",
            "Sipunculans have a trochophore larva and are probably annelids." to "சிப்புங்குலன்களுக்கு ட்ரோக்கோஃபோர் புழு உண்டு; அவை ஒருவேளை வளைதசையுடலிகள்.",
            "Priapulids moult their cuticle and belong to the Ecdysozoa." to "பிரையாப்புலிட்கள் தோலை உரிக்கின்றன; எக்டைசோசோவாவைச் சேர்ந்தவை."),
        q("u7-leech", 1, "Describe the external features of Hirudinaria granulosa.", "ஹிருடினேரியா கிரானுலோசாவின் வெளி அமைப்பை விவரிக்க.",
            "It is a large freshwater leech with an elongated, dorsoventrally flattened body." to "இது நீளமான, முதுகு-வயிறு தட்டையான உடலுள்ள பெரிய நன்னீர் அட்டை.",
            "An anterior sucker surrounds the mouth, and a large posterior sucker lies at the hind end." to "முன் உறிஞ்சி வாயைச் சூழ்ந்துள்ளது; பெரிய பின் உறிஞ்சி பின் முனையில் உள்ளது.",
            "The body has thirty-four fixed segments, each divided externally into annuli." to "உடலுக்கு முப்பத்து நான்கு நிலையான கண்டங்கள்; ஒவ்வொன்றும் வெளியில் அனுலிகளாகப் பிரிந்துள்ளது.",
            "Chaetae and parapodia are absent, and the skin has small papillae." to "சீட்டாக்கள், பாராபோடியா இல்லை; தோலில் சிறு பாப்பிலாக்கள் உள்ளன.",
            "Ocelli lie at the front, and the male and female genital pores open on the underside." to "முன்புறம் ஓசெல்லிகள் உள்ளன; ஆண், பெண் இனப்பெருக்கத் துளைகள் அடிப்பகுதியில் திறக்கின்றன."),
        q("u7-leech", 2, "Explain the adaptations of the leech to blood-sucking.", "இரத்தம் உறிஞ்சலுக்கான அட்டையின் தகவமைப்புகளை விளக்குக.",
            "Suckers allow it to attach to the host and to move by looping." to "உறிஞ்சிகள் விருந்தோம்பியில் ஒட்டவும் வளைந்து நகரவும் உதவுகின்றன.",
            "Three toothed jaws cut a Y-shaped wound, and a muscular pharynx pumps the blood." to "பற்களுடன் மூன்று தாடைகள் Y வடிவக் காயத்தை வெட்டுகின்றன; தசைத் தொண்டை இரத்தத்தை செலுத்துகிறது.",
            "Saliva contains an anticoagulant and an anaesthetic." to "உமிழ்நீரில் இரத்த உறைதல் தடுப்பியும் உணர்வு நீக்கியும் உள்ளன.",
            "The large crop with caeca stores a big meal, and slow digestion is aided by bacteria." to "குருட்டுக் குழல்களுடன் பெரிய கிராப் பெரிய உணவைச் சேமிக்கிறது; பாக்டீரியாக்கள் உதவும் மெதுவான செரிமானம்.",
            "Nephridia remove excess water, so the meal is concentrated." to "நெஃப்ரிடியா மிகை நீரை நீக்குவதால் உணவு செறிவாகிறது."),
        q("u7-annelid-excretion-asexual", 1, "Describe the nephridia of the earthworm.", "மண்புழுவின் நெஃப்ரிடியாவை விவரிக்க.",
            "Pheretima has many small nephridia in each segment, which is the plectonephric condition." to "பெரிட்டிமாவின் ஒவ்வொரு கண்டத்திலும் பல சிறு நெஃப்ரிடியா உள்ளன; இது பிளெக்டோநெஃப்ரிக் நிலை.",
            "Integumentary nephridia lie on the body wall, have no funnel and open to the outside." to "தோல்வழி நெஃப்ரிடியா உடல் சுவரில் உள்ளன; புனல் இல்லை; வெளியே திறக்கின்றன.",
            "Septal nephridia lie on the septa, have a funnel and open into the intestine." to "தடுப்புச் சுவர் நெஃப்ரிடியா தடுப்புச் சுவர்களில் உள்ளன; புனல் உண்டு; குடலுக்குள் திறக்கின்றன.",
            "Pharyngeal nephridia form tufts in the anterior segments and open into the pharynx." to "தொண்டை நெஃப்ரிடியா முன் கண்டங்களில் கொத்துகளாக அமைந்து தொண்டையில் திறக்கின்றன.",
            "Enteronephric types allow water to be reabsorbed, which saves water in dry soil." to "என்டெரோநெஃப்ரிக் வகைகள் நீர் மீண்டும் உறிஞ்சப்பட அனுமதிக்கின்றன; வறண்ட மண்ணில் நீரைச் சேமிக்கின்றன."),
        q("u7-annelid-excretion-asexual", 2, "Describe the asexual reproduction of polychaetes.", "பாலிகீட்டுகளின் பாலிலா இனப்பெருக்கத்தை விவரிக்க.",
            "In architomy, the body breaks into pieces which regenerate the missing parts." to "ஆர்க்கிடோமியில் உடல் துண்டுகளாக உடைந்து இல்லாத பகுதிகளை மீளுருவாக்குகிறது.",
            "In paratomy, new parts form before division, producing chains of zooids." to "பாராடோமியில் பிரிவதற்கு முன் புதிய பகுதிகள் உருவாகி சூயாய்டுகளின் சங்கிலிகளை உண்டாக்குகின்றன.",
            "In budding, outgrowths form new individuals, as in Syllis ramosa." to "அரும்புதலில் வளர்ச்சிகள் புதிய தனிநபர்களை உருவாக்குகின்றன; Syllis ramosa போல.",
            "In schizogamy, a stolon carrying gametes breaks away, as in Autolytus." to "ஸ்கிசோகாமியில் கேமீட்டுகளைச் சுமக்கும் ஸ்டோலன் பிரிகிறது; Autolytus போல.",
            "Epitoky, as in the heteronereis, is a sexual change and must be kept separate." to "ஹெட்டெரோநெரீஸ் போன்ற எபிடோக்கி பாலினப் பெருக்க மாற்றம்; தனியாக வைக்கப்பட வேண்டும்."),
        q("u7-minor-molluscs", 1, "Describe the structure and feeding of a bivalve.", "இருவோடுடலியின் அமைப்பையும் உணவூட்டத்தையும் விவரிக்க.",
            "The body is compressed and enclosed in two valves joined by a ligament and hinge." to "உடல் அழுந்தி, தசைநாரும் கீலும் இணைக்கும் இரு ஓடுகளில் அடைக்கப்பட்டுள்ளது.",
            "Two adductor muscles close the shell, and the ligament opens it." to "இரு மூடு தசைகள் ஓட்டை மூடுகின்றன; தசைநார் அதைத் திறக்கிறது.",
            "There is no head, radula or tentacles, and the group is called Acephala." to "தலை, ரேடுலா, உணர்நீட்சிகள் இல்லை; குழு அசெஃபாலா எனப்படுகிறது.",
            "Ciliated gills draw water in through the incurrent siphon and trap plankton in mucus." to "சிலியா செவுள்கள் உள் செல்லும் சைஃபன் வழி நீரை இழுத்துச் சளியில் பிளாங்க்டனைச் சிக்கவைக்கின்றன.",
            "Labial palps sort the food, and the wedge-shaped foot burrows or the byssus attaches the animal." to "உதட்டுத் தொடுகை உறுப்புகள் உணவைப் பிரிக்கின்றன; ஆப்பு வடிவப் பாதம் துளையிடுகிறது அல்லது பைசஸ் விலங்கை இணைக்கிறது."),
        q("u7-minor-molluscs", 2, "Write an account of the economic importance of Mollusca.", "மெல்லுடலிகளின் பொருளாதார முக்கியத்துவம் பற்றி எழுதுக.",
            "Oysters, mussels, clams and cephalopods are eaten as food." to "ஆயிஸ்டர், சிப்பி, கிளிஞ்சல், தலைக்காலிகள் உணவாக உண்ணப்படுகின்றன.",
            "Pearl oysters such as Pinctada fucata yield pearls, and chank and other shells give lime, buttons and ornaments." to "Pinctada fucata போன்ற முத்துச் சிப்பிகள் முத்து தருகின்றன; சங்கு, பிற ஓடுகள் சுண்ணாம்பு, பொத்தான், அணிகலன் தருகின்றன.",
            "Squid axons and Aplysia are used in research on nerves." to "கணவாய் அச்சு நரம்பிழைகளும் அப்ளைசியாவும் நரம்பு ஆய்வில் பயன்படுகின்றன.",
            "Teredo bores into timber, and Achatina and slugs damage crops." to "Teredo மரத்தில் துளையிடுகிறது; Achatina, ஸ்லக்குகள் பயிர்களைச் சேதப்படுத்துகின்றன.",
            "Lymnaea and other snails are intermediate hosts of flukes." to "லிம்னியா, பிற நத்தைகள் தட்டைப்புழுக்களின் இடைநிலைப் புரவலர்கள்."),
        q("u7-echino-classes", 1, "Describe the structure of a crinoid with reference to Antedon.", "ஆன்டிடானைக் குறிப்பிட்டு கிரைனாய்டின் அமைப்பை விவரிக்க.",
            "The body has a cup-shaped calyx of calcareous plates enclosing the viscera." to "உடலுக்கு உள்ளுறுப்புகளை அடைக்கும் சுண்ணாம்புத் தகடுகளாலான கிண்ண வடிவ கேலிக்ஸ் உண்டு.",
            "Five forked arms bear pinnules, and ambulacral grooves carry food to the mouth." to "ஐந்து பிரியும் கைகள் பின்னூல்களைத் தாங்குகின்றன; நடைப்பள்ளங்கள் உணவை வாய்க்கு எடுத்துச் செல்கின்றன.",
            "The mouth and anus are on the oral surface, and the tube feet have no suckers." to "வாயும் ஆசனவாயும் வாய்ப் பரப்பில்; குழல் கால்களுக்கு உறிஞ்சிகள் இல்லை.",
            "The adult Antedon is stalkless and clings with cirri, but the young pentacrinoid is stalked." to "முதிர்ந்த ஆன்டிடான் தண்டற்றது, சிர்ரிகளால் பற்றுகிறது; இளம் பென்டாகிரைனாய்டு தண்டுடையது.",
            "It is a suspension feeder and shows the evolution of free-living forms from stalked ancestors." to "இது தொங்கல் துகள் உண்ணி; தண்டுடைய மூதாதையரிலிருந்து தனித்து வாழும் வடிவங்களின் பரிணாமத்தைக் காட்டுகிறது."),
        q("u7-echino-classes", 2, "Write notes on the fossil classes of Echinodermata.", "முட்தோலிகளின் புதைபடிவ வகுப்புகள் பற்றிக் குறிப்பு எழுதுக.",
            "Cystoidea had globular, pored thecae and brachioles and were attached." to "சிஸ்டாய்டியாவுக்கு துளையுடைய உருண்டை தீகாக்கள், பிராக்கியோல்கள் இருந்தன; இணைந்தவை.",
            "Blastoidea had bud-shaped thecae, five ambulacra and hydrospires." to "பிளாஸ்டாய்டியாவுக்கு அரும்பு வடிவ தீகாக்கள், ஐந்து நடைப்பகுதிகள், ஹைட்ரோஸ்பைர்கள் இருந்தன.",
            "Edrioasteroidea were attached discs with five curved ambulacral areas." to "எட்ரியோஆஸ்டிராய்டியா ஐந்து வளைந்த நடைப்பகுதிகளுடன் இணைந்த வட்டுகள்.",
            "Heterostelea were asymmetrical, flattened forms with a stele, and their affinities are disputed." to "ஹெட்டெரோஸ்டெலியா ஸ்டீலுடன் சமச்சீரற்ற தட்டையான வடிவங்கள்; உறவு விவாதத்துக்குரியது.",
            "Ophiocistioidea were free-living and combined echinoid and holothurian features." to "ஒஃபியோசிஸ்டியாய்டியா தனித்து வாழ்ந்து எக்கினாய்டு, ஹோலோதூரியன் பண்புகளை இணைத்தவை."),
        q("u7-aurelia-mesenteries", 1, "Describe the life cycle of Aurelia.", "ஆரீலியாவின் வாழ்க்கைச் சுழற்சியை விவரிக்க.",
            "The sexes are separate, and fertilised eggs develop in the oral arms into planula larvae." to "பால்கள் தனி; கருவுற்ற முட்டைகள் வாய்க் கைகளில் பிளானுலா புழுக்களாக வளர்கின்றன.",
            "The planula settles and becomes a small polyp-like scyphistoma." to "பிளானுலா தங்கி சிறு பாலிப் போன்ற ஸ்கைஃபிஸ்டோமாவாகிறது.",
            "The scyphistoma divides transversely by strobilation to form a stack of discs, the strobila." to "ஸ்கைஃபிஸ்டோமா ஸ்ட்ரோபிலேஷனால் குறுக்காகப் பிரிந்து வட்டுகளின் அடுக்கான ஸ்ட்ரோபிலாவாகிறது.",
            "Each disc is released as an ephyra, which grows into the adult medusa." to "ஒவ்வொரு வட்டும் எஃபைராவாக விடுவிக்கப்பட்டு முதிர் மெடுசாவாக வளர்கிறது.",
            "The medusa is the conspicuous generation, unlike Obelia where the polyp colony dominates." to "ஓபீலியாவில் பாலிப் குடி ஆதிக்கம் செலுத்துவதற்கு மாறாக, மெடுசா தெளிவாகத் தெரியும் தலைமுறை."),
        q("u7-aurelia-mesenteries", 2, "Describe the mesenteries of a sea anemone.", "கடல் சீமந்திப்பூவின் மெசென்டரிகளை விவரிக்க.",
            "Mesenteries are double folds of gastrodermis enclosing mesoglea, running from the body wall inward." to "மெசென்டரிகள் மீசோகிளியாவை உள்ளடக்கிய இரைப்பைத்தோலின் இரட்டை மடிப்புகள்; உடல் சுவரிலிருந்து உள்நோக்கி ஓடுகின்றன.",
            "Complete mesenteries reach the pharynx, and incomplete ones do not." to "முழுமையான மெசென்டரிகள் தொண்டையை அடைகின்றன; முழுமையற்றவை அடைவதில்லை.",
            "They are arranged in pairs in cycles, in multiples of six in the Hexacorallia." to "அவை சுழற்சிகளாக இணைகளாக அமைந்துள்ளன; ஹெக்சாகோராலியாவில் ஆறின் மடங்குகள்.",
            "Retractor muscles on their faces shorten the body, and the filaments digest food." to "அவற்றின் பக்கங்களிலுள்ள இழுப்புத் தசைகள் உடலைச் சுருக்குகின்றன; இழைகள் உணவைச் செரிக்கின்றன.",
            "They increase the digestive surface, support the pharynx and carry the gonads." to "அவை செரிமான மேற்பரப்பை அதிகரிக்கின்றன, தொண்டைக்கு ஆதரவளிக்கின்றன, இனப்பெருக்கச் சுரப்பிகளைச் சுமக்கின்றன."),
        q("u7-tapeworm-host-parasite", 1, "Describe the life cycle of Taenia solium.", "Taenia solium-ன் வாழ்க்கைச் சுழற்சியை விவரிக்க.",
            "The adult lives in the human intestine, and gravid proglottids pass out with the faeces." to "முதிர்ந்தது மனிதக் குடலில் வாழ்கிறது; சூல் புரோகிளாட்டிட்டுகள் மலத்துடன் வெளியேறுகின்றன.",
            "The pig swallows the eggs, and the oncosphere bores through the gut wall into the blood." to "பன்றி முட்டைகளை விழுங்குகிறது; ஆன்கோஸ்ஃபியர் குடல் சுவரைத் துளைத்து இரத்தத்துக்குள் செல்கிறது.",
            "In the muscles, it develops into the cysticercus, giving measly pork." to "தசைகளில் அது சிஸ்டிசெர்கஸாக வளர்ந்து மீசிலி போர்க் ஆகிறது.",
            "Man is infected by eating raw or undercooked measly pork; the scolex everts and attaches." to "பச்சையான அல்லது வேகாத மீசிலி போர்க்கை உண்பதால் மனிதன் தொற்றடைகிறான்; ஸ்கொலெக்ஸ் வெளிப்புறம் திரும்பி இணைகிறது.",
            "Swallowing eggs causes cysticercosis in man, a separate risk." to "முட்டைகளை விழுங்குவது மனிதனில் சிஸ்டிசெர்கோசிஸை உண்டாக்குகிறது; தனி ஆபத்து."),
        q("u7-tapeworm-host-parasite", 2, "Explain the adaptations of a tapeworm to parasitic life.", "நாடாப்புழுவின் ஒட்டுண்ணி வாழ்க்கைக்கான தகவமைப்புகளை விளக்குக.",
            "The scolex has suckers and hooks for attachment." to "ஸ்கோலெக்ஸில் இணைவதற்கு உறிஞ்சிகளும் கொக்கிகளும் உண்டு.",
            "There is no gut, and food is absorbed through the tegument with microtriches." to "குடல் இல்லை; மைக்ரோட்ரிக்குகளுடன் டெகுமெண்ட் வழியே உணவு உறிஞ்சப்படுகிறது.",
            "Respiration is anaerobic, with stored glycogen." to "சுவாசம் காற்றில்லாதது; கிளைக்கோஜன் சேமிக்கப்படுகிறது.",
            "The worm is hermaphrodite and produces very many eggs." to "புழு இருபால் உயிரி; மிக அதிக முட்டைகளை உற்பத்தி செய்கிறது.",
            "A thick-shelled egg and a larval stage in an intermediate host help the cycle to continue." to "தடித்த ஓட்டு முட்டையும் இடைநிலைப் புரவலரிலுள்ள புழு நிலையும் சுழற்சி தொடர உதவுகின்றன."),
        q("u7-protozoa-economics", 1, "Write an account of the harmful protozoa and their economic effects.", "தீங்கான புரோட்டோசோவாக்களும் அவற்றின் பொருளாதார விளைவுகளும் பற்றி எழுதுக.",
            "Plasmodium causes malaria, spread by Anopheles, with lost work and costs of control." to "Plasmodium அனோஃபிலிஸ் பரப்பும் மலேரியாவை உண்டாக்குகிறது; இழந்த வேலையும் கட்டுப்பாட்டுச் செலவும் ஏற்படுகின்றன.",
            "Entamoeba histolytica and Giardia cause dysentery and diarrhoea through contaminated water." to "Entamoeba histolytica, Giardia மாசடைந்த நீர் வழியே வயிற்றுப்போக்கை உண்டாக்குகின்றன.",
            "Leishmania donovani causes kala-azar, spread by sandflies." to "Leishmania donovani மணல் ஈக்கள் பரப்பும் கறுப்புக் காய்ச்சலை உண்டாக்குகிறது.",
            "Eimeria, Babesia and Trypanosoma cause losses in poultry and livestock." to "Eimeria, Babesia, Trypanosoma கோழிகள், கால்நடைகளில் இழப்புகளை உண்டாக்குகின்றன.",
            "Nosema bombycis causes pebrine in silkworms, and Pasteur showed how to control it." to "Nosema bombycis பட்டுப்புழுக்களில் பெப்ரினை உண்டாக்குகிறது; அதைக் கட்டுப்படுத்தும் வழியை பாஸ்டர் காட்டினார்."),
        q("u7-protozoa-economics", 2, "Describe the useful roles of the Protozoa.", "புரோட்டோசோவாக்களின் பயனுள்ள பங்குகளை விவரிக்க.",
            "Free-living protozoa are links in aquatic and soil food webs." to "தனித்து வாழும் புரோட்டோசோவாக்கள் நீர், மண் உணவு வலைகளில் இணைப்புகள்.",
            "Ciliates in activated sludge clear bacteria and indicate the state of sewage treatment." to "செயல்படுத்தப்பட்ட கசடிலுள்ள சிலியேட்டுகள் பாக்டீரியாவை அகற்றி சுத்திகரிப்பின் நிலையைக் குறிக்கின்றன.",
            "Trichonympha helps termites to digest cellulose, and rumen ciliates take part in digestion." to "Trichonympha கரையான்களுக்கு செல்லுலோஸைச் செரிக்க உதவுகிறது; இரைப்பைச் சிலியேட்டுகள் செரிமானத்தில் பங்கேற்கின்றன.",
            "Foraminiferan and radiolarian shells form chalk, limestone and oozes and aid oil exploration." to "ஃபோராமினிஃபெரன், ரேடியோலேரியன் ஓடுகள் சுண்ணக்கட்டி, சுண்ணாம்புக்கல், சேறுகளை உருவாக்கி எண்ணெய்த் தேடலுக்கு உதவுகின்றன.",
            "Paramecium and Tetrahymena are model organisms in genetics and cell biology." to "Paramecium, Tetrahymena மரபியல், செல் உயிரியலில் மாதிரி உயிரிகள்."),
    ).groupBy { it.chapterId }
}
